from typing import List

class Solution:
    def removeDuplicates(self, nums: List[int]) -> int:
        i = 1
        while i < len(nums):
            # In a sorted array, equal neighbors are duplicates.
            if nums[i] == nums[i - 1]:
                del nums[i]
            else:
                i += 1
        return len(nums)

