from typing import List

class Solution:
    def removeDuplicates(self, nums: List[int]) -> int:
        unique = []
        for value in nums:
            # Append only the first value from each duplicate run.
            if not unique or unique[-1] != value:
                unique.append(value)
        for i, value in enumerate(unique):
            nums[i] = value
        return len(unique)

